namespace BioChain.AnalysisFramework.Mbti;

// 16 MBTI prototype descriptions broken down per-chemical, mirroring how
// the 27 analyzing agents write individual chemical_observation reasoning
// records. Each entry is a (typeCode, chemical) → reasoning text that uses
// the same PhD-level neurochemical language (receptors, pathways, brain
// regions, dose-response) that agents produce.
//
// Classification works by comparing a person's actual per-chemical
// observation embeddings against each type's per-chemical prototype
// embeddings — accumulating cosine similarity per type across all
// observed chemicals, then ranking. This preserves chemical-specific
// signal that mean-pooling destroys.
public static class MbtiPrototypes
{
    public const int PrototypeVersion = 7;

    // Key: (MBTI type, chemical) → reasoning text matching agent output style
    public static readonly Dictionary<(string Type, string Chemical), string> ChemicalDescriptions = new()
    {
        // ══════════════════════════════════════════════════════════════
        // INTJ — The Architect
        // ══════════════════════════════════════════════════════════════
        [("INTJ", "acetylcholine")] = "Acetylcholine elevated — muscarinic M1 receptor activation in PFC and hippocampus sustains deep parasympathetic processing. Nucleus basalis of Meynert projections drive prolonged solitary concentration and high signal-to-noise attentional discrimination. High acetylcholine with low oxytocin indicates attentional depth without social-bonding modulation — pure cognitive engagement.",
        [("INTJ", "glutamate")] = "Glutamate elevated — NMDA receptor coincidence detection in hippocampal CA1 enables abstract pattern recognition and systems-level model construction. AMPA receptor fast excitation in dorsolateral PFC supports working memory for strategic planning. High glutamate with high GABA prevents excitotoxic overflow while maintaining sharp associative processing.",
        [("INTJ", "gaba")] = "GABA elevated — GABA-A ionotropic fast inhibition via interneuron networks in anterior cingulate suppresses irrelevant social stimuli and emotional noise. Tonic inhibition in amygdala dampens affiliative reward-seeking. High GABA with low cortisol produces calm safety for focused internal processing rather than anxious numbing.",
        [("INTJ", "dopamine")] = "Dopamine moderate — D1 Gs-coupled excitatory tone in PFC working memory maintains strategic goal representations. Mesocortical pathway active but mesolimbic social reward subdued. Tonic rather than phasic firing pattern — sustained executive function over novelty bursts. Not seeking external reward — driven by internal model completion.",
        [("INTJ", "serotonin")] = "Serotonin low — 5-HT2A receptor activity minimal in sensory cortex — reduced present-moment sensory focus, replaced by future-oriented abstract processing. Low 5-HT2C inhibition of VTA dopamine allows sustained mesocortical activation for long-range planning. Low serotonin does not create impulsivity because GABA provides inhibitory control instead.",
        [("INTJ", "norepinephrine")] = "Norepinephrine moderate — alpha-2A receptor PFC enhancement at moderate levels supports selective attention filter without arousal overflow. Locus coeruleus phasic mode for targeted focus rather than tonic broad scanning. Inverted-U at optimal — not hypervigilant, but precisely alert to relevant information.",
        [("INTJ", "testosterone")] = "Testosterone elevated — androgen receptor activation in dorsolateral PFC enhances systemizing and spatial-analytical processing. Baron-Cohen empathizing-systemizing fetal testosterone signature. No corresponding social dominance signaling — androgen effects channeled through cortical executive circuits not amygdalar social-dominance circuits.",
        [("INTJ", "cortisol")] = "Cortisol moderate — GR low-affinity phasic activation in PFC drives closure-seeking under ambiguity. CRH release from paraventricular nucleus triggers structured planning as anxiety-reduction strategy. Acute cortisol at optimal range sharpens attention and memory consolidation without hippocampal GR downregulation.",
        [("INTJ", "melatonin")] = "Melatonin elevated — SCN-mediated circadian withdrawal signaling drives deep parasympathetic restoration through pineal-driven solitude cycles. MT1/MT2 receptor hypersensitivity in suprachiasmatic nucleus orchestrates neural quieting and default mode network consolidation during evening withdrawal. Dorsomedial PFC and precuneus deactivation of task-positive networks permits introspective model refinement. High melatonin with cognitive autonomy preference — solitary circadian recharge fuels internal coherence rather than social engagement.",
        [("INTJ", "oxytocin")] = "Oxytocin low — OXTR downregulation across hippocampal and dorsomedial PFC reward circuits minimizes affiliative signaling interference with self-referential processing. Internal model fidelity prioritized over social consensus — default mode network dominance preserves cognitive autonomy from oxytocin-mediated social interrupt. Precuneus and posterior cingulate self-referential loops operate without peptidergic bonding modulation. Low oxytocin is not deficit — it is trait-level preservation of introspective consolidation depth.",
        [("INTJ", "oxytocin_h")] = "Hormonal oxytocin low — hypothalamic paraventricular release minimal, preserving cognitive autonomy from social approach interrupts. Internal processing protected from affiliative signaling — dorsomedial PFC self-referential circuits operate without hypothalamic social-drive modulation. Group contexts impose metabolic cost on solitary processing depth. One-on-one strategic interaction preserves introspective consolidation capacity.",
        [("INTJ", "vasopressin")] = "Vasopressin moderate — V1a receptor activation in lateral septum supports loyalty to select individuals and territorial boundary-maintenance. Pair-bonding circuitry engaged without broad social approach. Vigilance in protecting established intellectual territory and close relationships.",
        [("INTJ", "bdnf")] = "BDNF elevated — TrkB receptor signaling in hippocampus supports introverted neuroplasticity — enhanced long-term potentiation for internal model refinement. Val66Met polymorphism pattern favoring solo cognitive learning over social learning. BDNF-NMDA-CREB pathway active for deep consolidation of abstract frameworks.",
        [("INTJ", "dynorphin")] = "Dynorphin moderate — kappa-opioid receptor social satiation signaling after group exposure drives withdrawal to restore internal coherence. KOR activation dampens residual social dopamine in hippocampal-PFC circuits, creating strong preference for solitary cognitive recharge. Precuneus and dorsomedial PFC default mode re-engagement requires KOR-mediated clearing of interpersonal processing load. Social fatigue signal redirects energy toward introspective consolidation and self-referential model reconstruction.",
        [("INTJ", "crh")] = "CRH moderate — CRHR1 activation in bed nucleus of stria terminalis triggers closure-seeking when facing ambiguity. Physiological cost of open-ended situations drives structured resolution. CRH-cortisol cascade mobilizes planning behavior rather than avoidance.",
        [("INTJ", "endorphins")] = "Endorphins low-moderate — mu-opioid reward derived from solitary mastery and internal insight completion rather than interpersonal warmth. Periaqueductal gray activation from cognitive closure and abstract model completion, not from social network engagement. Beta-endorphin release tied to hippocampal pattern-completion events during deep focus — solitary processing depth generates its own opioid reinforcement independent of affiliative context.",
        [("INTJ", "endocannabinoid")] = "Endocannabinoid low-moderate — CB1 retrograde signaling provides enough flexibility for strategic pivots but not the behavioral looseness that resists all structure. Anandamide tone supports focused problem-solving, not open-ended wandering.",
        [("INTJ", "adrenaline")] = "Adrenaline low-moderate — beta-adrenergic activation minimal except during acute strategic challenge. Sympathetic arousal controlled and focused. No baseline hypervigilance — calm sustained execution.",
        [("INTJ", "dhea")] = "DHEA moderate — antagonizes cortisol-driven anxiety to maintain clear strategic thinking. DHEA:cortisol ratio supports resilience under uncertainty. Neurosteroid modulation preserves executive function during closure-seeking.",
        [("INTJ", "enkephalins")] = "Enkephalins low — delta-opioid hedonic reward from solitary aesthetic experience and contemplative processing. Quiet contentment from cognitive mastery — DOR activation in hippocampal-PFC circuits during internal discovery and abstract pattern recognition. Pleasure derived from introspective consolidation depth, not from interpersonal warmth or group play.",
        [("INTJ", "estradiol")] = "Estradiol low-moderate — ERalpha in hippocampus supports memory consolidation without driving social-emotional empathic expression. Cognitive effects present, affiliative effects muted.",
        [("INTJ", "npy")] = "NPY moderate — Y1/Y2 receptor activity in amygdala provides stress buffering during strategic planning. Anxiety reduction without social approach — calm solitary focus.",
        [("INTJ", "orexin")] = "Orexin moderate — OX1R activation in lateral hypothalamus fires during intellectual problem-solving but not social exploration. Arousal for cognitive challenge, not physical or social novelty.",
        [("INTJ", "progesterone")] = "Progesterone low-moderate — allopregnanolone GABA-A modulation provides subtle anxiolytic support for sustained concentration without emotional warmth expression.",
        [("INTJ", "prolactin")] = "Prolactin low — tuberoinfundibular pathway D2 inhibition intact. Minimal nurturing motivation or caregiving satisfaction. Achievement over affiliation.",
        [("INTJ", "substance_p")] = "Substance P low — NK1 receptor activation in amygdala minimal. Pain and emotional distress signaling subdued. High pain tolerance and emotional stoicism.",
        [("INTJ", "thyroid")] = "Thyroid moderate — T3/T4 HPT axis activation supports sustained metabolic demand for deep cognitive processing. Thyroxine levels maintain energy for prolonged intellectual work without hyperarousal.",

        // ══════════════════════════════════════════════════════════════
        // INTP — The Logician
        // ══════════════════════════════════════════════════════════════
        [("INTP", "dopamine")] = "Dopamine elevated — D1 Gs-coupled excitatory activation in mesocortical pathway sustains intellectual curiosity and prediction-error driven exploration. VTA tonic firing supports broad scanning of abstract logical systems rather than focused goal pursuit. Phasic bursts reward novel theoretical connections. High dopamine with low serotonin — obsessive intellectual pursuit without premature satisfaction.",
        [("INTP", "acetylcholine")] = "Acetylcholine elevated — muscarinic M1 parasympathetic long-pathway dominates. Nucleus basalis cholinergic projections to hippocampus drive deep sustained attention on internal representations and theoretical model-building. High acetylcholine with high dopamine creates focused learning state.",
        [("INTP", "glutamate")] = "Glutamate elevated — NMDA receptor coincidence detection in prefrontal-hippocampal circuits enables rapid associative pattern detection and theoretical framework construction. mGluR metabotropic modulation supports cognitive flexibility during theoretical exploration.",
        [("INTP", "endocannabinoid")] = "Endocannabinoid elevated — CB1 retrograde signaling in PFC provides cognitive flexibility and resistance to premature closure. Anandamide-mediated extinction of rigid patterns. FAAH degradation supports sustained exploratory flexibility. High endocannabinoid resists rigid scheduling — open-ended exploration is default mode.",
        [("INTP", "gaba")] = "GABA low-moderate — GABA-B metabotropic inhibition in temporal cortex filters emotional noise but GABA-A fast inhibition reduced in frontal circuits — less behavioral constraint, more idea generation. Lower inhibitory control than INTJ — ideas flow more freely but with less structured execution.",
        [("INTP", "serotonin")] = "Serotonin low — minimal 5-HT1A autoreceptor sensitivity in dorsal raphe. No social consensus need. Low serotonin with high dopamine creates obsessive intellectual pursuit pattern — limerence-like engagement with ideas rather than people.",
        [("INTP", "norepinephrine")] = "Norepinephrine moderate — locus coeruleus tonic mode creates defocused scanning attention — broad associative reach rather than selective filtering. Alpha-2A at suboptimal for focused execution but ideal for divergent idea generation.",
        [("INTP", "cortisol")] = "Cortisol low — minimal HPA axis activation from unstructured situations. GR-mediated closure drive absent — open-ended exploration is not physiologically costly. Low cortisol with high endocannabinoid — ambiguity is comfortable.",
        [("INTP", "testosterone")] = "Testosterone moderate — androgen receptor activation supports analytical reasoning and spatial thinking without social dominance motivation. Systemizing without competing.",
        [("INTP", "melatonin")] = "Melatonin elevated — SCN-mediated circadian withdrawal signaling initiates parasympathetic restoration through pineal-driven solitude cycles. MT1/MT2 receptor sensitivity in suprachiasmatic nucleus gates evening transition into default mode network consolidation. Precuneus and dorsomedial PFC self-referential processing deepens as neural quieting suppresses task-positive interrupts. Solitary circadian recharge enables internal model construction — cognitive autonomy preserved through melatonin-mediated withdrawal from environmental engagement.",
        [("INTP", "bdnf")] = "BDNF elevated — TrkB receptor signaling in hippocampus and cortex supports continuous synaptic remodeling and learning capacity. Neuroplasticity engine for constant model revision. BDNF-NMDA-CREB pathway keeps theoretical frameworks perpetually updatable.",
        [("INTP", "oxytocin")] = "Oxytocin low — OXTR downregulation in hippocampal and dorsomedial PFC self-referential circuits minimizes affiliative signaling disruption of internal model construction. Default mode network dominance over social processing — cognitive autonomy preserved from oxytocin-driven consensus-seeking. Precuneus introspective loops operate without peptidergic bonding modulation. Not antisocial — internal model fidelity simply prioritized over social consensus.",
        [("INTP", "orexin")] = "Orexin elevated — OX1R/OX2R in lateral hypothalamus fires during intellectual exploration contexts. Exploration drive potentiates VTA dopamine specifically during idea-generation, not physical activity.",
        [("INTP", "npy")] = "NPY elevated — Y1/Y2 receptors in amygdala reduce physiological cost of ambiguity. Uncertainty is tolerable — no stress-driven closure. NPY buffering allows indefinite exploration without anxiety pressure to resolve.",
        [("INTP", "adrenaline")] = "Adrenaline low — minimal sympathetic activation. No fight-or-flight arousal pattern. Beta-adrenergic tone subdued — calm intellectual engagement without urgency.",
        [("INTP", "crh")] = "CRH low — CRHR1 minimal activation. No physiological cost from open-ended exploration or unresolved questions. CRH-cortisol cascade absent — comfort with perpetual uncertainty.",
        [("INTP", "dhea")] = "DHEA elevated — high DHEA:cortisol ratio maintains cognitive flexibility and resilience. Neurosteroid buffering prevents stress-driven closure, supports sustained theoretical exploration.",
        [("INTP", "dynorphin")] = "Dynorphin low — kappa-opioid social satiation signaling minimal because baseline social engagement is already low. KOR-mediated dampening of residual social dopamine in hippocampal-PFC circuits unnecessary when default mode network already dominates. Internal coherence maintained through introspective consolidation rather than withdrawal recovery. Solitary cognitive recharge is continuous state, not post-social restoration.",
        [("INTP", "endorphins")] = "Endorphins low — mu-opioid reward from solitary mastery and internal insight rather than interpersonal warmth. Periaqueductal gray activation tied to cognitive completion events — hippocampal pattern-recognition breakthroughs during deep focus, not social network engagement. Beta-endorphin release from contemplative processing depth and abstract model construction. Solitary processing generates its own opioid reinforcement independent of affiliative context.",
        [("INTP", "enkephalins")] = "Enkephalins low — delta-opioid hedonic reward from solitary internal discovery and contemplative processing. DOR activation in hippocampal-PFC circuits during abstract pattern recognition provides quiet contentment from cognitive mastery. Pleasure derived from introspective consolidation depth and theoretical breakthrough, not from interpersonal warmth or group play.",
        [("INTP", "estradiol")] = "Estradiol low — ERalpha expression minimal in social-emotional circuits. No affiliative empathic expression drive. Cognitive effects of estradiol present without social warmth.",
        [("INTP", "oxytocin_h")] = "Hormonal oxytocin low — hypothalamic paraventricular release minimal, preserving internal processing from social approach interrupts. Cognitive autonomy maintained — dorsomedial PFC and hippocampal self-referential circuits protected from hypothalamic affiliative signaling. Solitary processing depth undisturbed by social drive. Interaction selective and intellectually motivated, not affiliatively driven.",
        [("INTP", "progesterone")] = "Progesterone low — allopregnanolone GABA-A modulation minimal. No emotional warmth or nurturing stabilization. Intellectual focus without affective depth.",
        [("INTP", "prolactin")] = "Prolactin low — tuberoinfundibular D2 inhibition strong. No caregiving satisfaction or nurturing motivation. Achievement through understanding, not through helping.",
