        [("ENTJ", "dopamine")] = "Dopamine elevated — phasic burst firing in VTA-NAc mesolimbic pathway drives social achievement reward and resource acquisition. D1 Gs-coupled excitatory tone in PFC sustains strategic goal-directed executive function. High dopamine with low serotonin 5-HT2C disinhibition — reward pursuit uninhibited by premature satisfaction.",
        [("ENTJ", "norepinephrine")] = "Norepinephrine elevated — beta-adrenergic receptor arousal in locus coeruleus amplifies alertness during social challenge and strategic decision-making. Phasic mode under competitive pressure. High NE with high testosterone — assertive arousal.",
        [("ENTJ", "glutamate")] = "Glutamate elevated — AMPA receptor fast excitatory transmission in DLPFC supports rapid systems-level strategic computation. NMDA coincidence detection for organizational pattern recognition.",
        [("ENTJ", "gaba")] = "GABA moderate — GABA-A interneuron gating in anterior cingulate enables decisive action by suppressing emotional deliberation and empathic interference with logical optimization. Enough inhibition for focused execution without overcontrol.",
        [("ENTJ", "serotonin")] = "Serotonin low — 5-HT2C inhibition of dopamine VTA minimal — unbraked reward pursuit and competitive drive. Low serotonin does not create mood instability because testosterone and norepinephrine provide motivational stability.",
        [("ENTJ", "testosterone")] = "Testosterone elevated — androgen receptor activation in amygdala and PFC potentiates competitive drive and dominance-hierarchy navigation. Social status pursuit via hypothalamic-pituitary-gonadal axis signaling. High testosterone with high dopamine — bold decisive leadership.",
        [("ENTJ", "cortisol")] = "Cortisol moderate-high — HPA axis activation channels through GR-mediated PFC executive function enhancement rather than amygdala-driven avoidance. Stress mobilizes structured action not withdrawal. Acute cortisol potentiates dopamine for urgent goal pursuit.",
        [("ENTJ", "adrenaline")] = "Adrenaline moderate — beta-adrenergic acute activation via sympathetic nervous system supports decisive action under operational pressure. Adrenaline enhances performance in crisis without destabilizing focus.",
