        [("ENTJ", "dhea")] = "DHEA moderate-high — antagonizes cortisol to maintain aggressive confidence under pressure. DHEA:cortisol ratio supports assertive decision-making without anxiety paralysis.",
        [("ENTJ", "dynorphin")] = "Dynorphin low — minimal social fatigue signal as KOR social satiation absent in ventral striatum group reward circuits. Unlimited group engagement capacity — no withdrawal drive from social interaction. Anterior insula and temporoparietal junction interpersonal processing sustained without kappa-opioid dampening. Social energy amplification continues indefinitely without depletion signal — group status signaling maintains ventromedial PFC activation.",
        [("ENTJ", "endocannabinoid")] = "Endocannabinoid low — CB1 flexibility minimal. Proven strategies and hierarchical structures dominate. Improvisation limited — prefers established frameworks.",
        [("ENTJ", "enkephalins")] = "Enkephalins low — delta-opioid hedonic reward from group activities and shared competitive success rather than solitary contemplation. DOR activation in ventral striatum during interpersonal achievement — contentment from social connection through organizational dominance. Ventromedial PFC social reward prediction reinforces group status signaling. Pleasure from group reward cascade, not from solitary aesthetic experience.",
        [("ENTJ", "estradiol")] = "Estradiol low-moderate — ERalpha in hippocampus supports memory without affiliative empathic expression. Cognitive effects without warmth or nurturing drive.",
        [("ENTJ", "melatonin")] = "Melatonin low-moderate — suppressed circadian gating as ventral striatum social reward cascades override pineal onset signals. Sympathetic engagement extends into evening hours — anterior insula and temporoparietal junction remain active during group coordination well past typical melatonin rise. Social arousal preventing melatonin onset through ventromedial PFC status-monitoring circuits that sustain interpersonal engagement. Group energy amplification delays parasympathetic transition indefinitely.",
