        [("INFJ", "acetylcholine")] = "Acetylcholine elevated — muscarinic M1 receptor dominance in PFC and hippocampus sustains deep introspective processing and symbolic-intuitive pattern recognition in human behavior. Parasympathetic long-pathway processing dominates.",
        [("INFJ", "serotonin")] = "Serotonin elevated — 5-HT1A receptor activation in dorsal raphe and limbic circuits supports values-alignment and prosocial harm-aversion. Moral judgment modulation through serotonergic tone. Moderate serotonin with high acetylcholine creates contemplative values-depth.",
        [("INFJ", "glutamate")] = "Glutamate moderate — NMDA coincidence detection in hippocampus supports abstract meaning consolidation during solitary reflection. Pattern completion for human-behavioral insights rather than mechanical systems.",
        [("INFJ", "gaba")] = "GABA moderate — tonic inhibition provides emotional steadiness for principled conviction without impulsive reactivity. Enough inhibitory control for measured values-based responding.",
        [("INFJ", "melatonin")] = "Melatonin elevated — SCN-mediated circadian withdrawal signaling orchestrates deep parasympathetic restoration through pineal-driven solitude cycles. MT1/MT2 receptor sensitivity gates evening transition into default mode network consolidation for values-integration and symbolic processing. Dorsomedial PFC and precuneus self-referential circuits deepen during neural quieting. Introspective consolidation of human-behavioral patterns requires melatonin-mediated cognitive recharge in solitary withdrawal.",
        [("INFJ", "cortisol")] = "Cortisol moderate — CRH CRHR1 in bed nucleus of stria terminalis drives closure-seeking on interpersonal ambiguity. GR phasic activation when social harmony is threatened — seeks resolution not avoidance.",
