        [("INFJ", "estradiol")] = "Estradiol moderate — ERalpha in hippocampus enhances social-emotional memory encoding for meaningful interpersonal patterns. Empathy expressed through insight rather than action.",
        [("INFJ", "oxytocin")] = "Oxytocin moderate-selective — OXTR expression limited to hippocampal and dorsomedial PFC self-referential circuits that support empathic insight through internal model construction rather than affiliative approach. Self-referential processing dominance channels selective bonding through introspective consolidation — understanding others via default mode network simulation rather than direct social reward. Internal model fidelity of human patterns prioritized over broad social consensus. Intimate meaning-driven connection preserves cognitive autonomy.",
        [("INFJ", "vasopressin")] = "Vasopressin elevated — V1a receptor in ventral pallidum creates deep loyalty bonds with select individuals. Pair-bonding circuitry engaged without broad social approach motivation.",
        [("INFJ", "bdnf")] = "BDNF elevated — TrkB signaling enables insight generation and abstract meaning consolidation. Neuroplasticity directed toward understanding human patterns, not mechanical systems.",
        [("INFJ", "dynorphin")] = "Dynorphin moderate — kappa-opioid social satiation signaling after group exposure drives withdrawal to restore internal coherence. KOR activation dampens residual social dopamine in hippocampal-PFC circuits, enabling default mode network re-engagement for introspective consolidation. Precuneus self-referential processing requires KOR-mediated clearing of interpersonal processing load. Social fatigue redirects energy toward solitary values-integration and cognitive recharge.",
        [("INFJ", "dopamine")] = "Dopamine low-moderate — D2 social reward-seeking in ventral striatum subdued. External validation not reinforcing. Mesocortical pathway supports insight-seeking but not sensation-seeking.",
        [("INFJ", "adrenaline")] = "Adrenaline low — minimal sympathetic activation. Beta-adrenergic arousal subdued. Calm contemplative presence without fight-or-flight reactivity.",
        [("INFJ", "crh")] = "CRH moderate — CRHR1 activation when interpersonal values-alignment is threatened. Physiological drive to resolve moral-social dissonance, not to avoid it.",
        [("INFJ", "dhea")] = "DHEA moderate — buffers cortisol-driven closure pressure to maintain contemplative values-depth. DHEA:cortisol ratio supports principled conviction under stress.",
        [("INFJ", "endocannabinoid")] = "Endocannabinoid low-moderate — CB1 flexibility limited. Strong values-structure with strategic adaptability for achieving principled outcomes.",
        [("INFJ", "endorphins")] = "Endorphins moderate — mu-opioid reward from solitary contemplative processing and internal insight rather than broad social warmth. Periaqueductal gray activation from cognitive completion of human-behavioral models during deep focus. Beta-endorphin release tied to hippocampal pattern-completion during introspective consolidation — meaningful connection with select individuals generates opioid reinforcement through shared depth, not through social network scale.",
        [("INFJ", "enkephalins")] = "Enkephalins moderate — delta-opioid hedonic reward from solitary aesthetic experience and contemplative values-processing. DOR activation in hippocampal-PFC circuits during internal discovery of human meaning patterns. Quiet contentment from cognitive mastery of moral-symbolic frameworks — introspective consolidation depth generates subtle pleasure independent of group play or social warmth.",
        [("INFJ", "norepinephrine")] = "Norepinephrine low-moderate — locus coeruleus tonic mode subdued. Alert to interpersonal emotional undercurrents without hypervigilance. Selective attentional focus on human meaning.",
        [("INFJ", "npy")] = "NPY moderate — Y1/Y2 amygdala buffering provides emotional steadiness for principled stands. Anxiety reduction supports values-conviction without destabilizing stress.",
        [("INFJ", "orexin")] = "Orexin low-moderate — OX1R activation for values-driven pursuits, not novelty-seeking. Exploration drive focused on human meaning and moral clarity.",
        [("INFJ", "oxytocin_h")] = "Hormonal oxytocin moderate-selective — hypothalamic paraventricular release minimal outside intimate meaningful contexts, preserving solitary processing depth. Cognitive autonomy protected from broad social approach signaling. Dorsomedial PFC self-referential circuits maintain introspective consolidation capacity — deep bonding with few preserves internal coherence rather than dispersing energy across group synchronization demands.",
        [("INFJ", "prolactin")] = "Prolactin moderate — tuberoinfundibular activation supports nurturing through insight and emotional guidance. Caregiving expressed through values-alignment facilitation.",
        [("INFJ", "substance_p")] = "Substance P low-moderate — NK1 receptor activation subdued. Emotional pain processed internally without overwhelming distress signaling. High tolerance for moral-emotional complexity.",
        [("INFJ", "testosterone")] = "Testosterone low-moderate — androgen effects minimal. No dominance-seeking or competitive drive. Influence through insight and values-clarity, not assertion.",
        [("INFJ", "thyroid")] = "Thyroid moderate — T3/T4 supports sustained contemplative processing. HPT axis provides energy for deep empathic-intuitive work without hyperarousal.",

        // ══════════════════════════════════════════════════════════════
        // INFP — The Mediator
        // ══════════════════════════════════════════════════════════════
        [("INFP", "acetylcholine")] = "Acetylcholine elevated — muscarinic M1 parasympathetic processing in hippocampal-PFC circuits sustains self-reflective internal world of values and identity construction. Deep encoding of personal meaning and moral narrative.",
        [("INFP", "serotonin")] = "Serotonin moderate — 5-HT2A receptor activation in default mode network facilitates abstract idealistic thinking and metaphorical pattern connection. Values-depth processing without rigid rule-enforcement.",
        [("INFP", "endocannabinoid")] = "Endocannabinoid elevated — anandamide FAAH-regulated CB1 signaling in PFC provides flexibility and resistance to externally imposed structure. Extinction of rigid schedule-adherence patterns. High endocannabinoid with low cortisol — organic flow without anxiety.",
        [("INFP", "dopamine")] = "Dopamine low-moderate — mesolimbic social reward not dominant. No external validation seeking. Mesocortical supports values-aligned creative exploration — intrinsic motivation only.",
        [("INFP", "cortisol")] = "Cortisol low — minimal GR sensitivity in hippocampus. Conflict triggers HPA axis dysregulation and withdrawal rather than confrontation. Low cortisol with high endocannabinoid — avoids rather than resolves conflict.",
        [("INFP", "melatonin")] = "Melatonin elevated — SCN-mediated circadian withdrawal signaling drives parasympathetic restoration through pineal-driven solitude cycles. MT1/MT2 receptor sensitivity gates evening transition into default mode network consolidation for values-integration and identity construction. Precuneus and dorsomedial PFC self-referential processing deepens as neural quieting suppresses external demands. Introspective consolidation of personal meaning requires melatonin-mediated cognitive recharge in solitary reflective withdrawal.",
        [("INFP", "endorphins")] = "Endorphins moderate — mu-opioid reward from solitary contemplative processing and internal aesthetic experience. Periaqueductal gray activation from creative insight and values-alignment during deep focus. Beta-endorphin release tied to hippocampal pattern-completion during introspective consolidation — OPRM1 activation from authentic inner discovery. Selective meaningful connection generates opioid reinforcement through shared depth, not social network scale.",
        [("INFP", "enkephalins")] = "Enkephalins moderate — delta-opioid hedonic reward from solitary aesthetic experience and contemplative values-processing. DOR activation in hippocampal-PFC circuits during internal discovery of personal meaning and creative pattern recognition. Quiet contentment from cognitive mastery of identity-narrative coherence — introspective consolidation depth generates subtle pleasure from living authentically, independent of group play.",
        [("INFP", "bdnf")] = "BDNF elevated — TrkB-mediated synaptic plasticity in hippocampus supports creative associative cognition and novel pattern formation. Idealistic imagination rooted in neuroplasticity.",
        [("INFP", "oxytocin")] = "Oxytocin context-dependent — OXTR downregulation in large-group contexts preserves self-referential processing dominance in dorsomedial PFC and precuneus. Internal model fidelity of personal values prioritized over social consensus. Default mode network introspective loops operate with selective peptidergic modulation only in intimate dyadic bonds. Cognitive autonomy protected from broad affiliative signaling — depth of introspective consolidation over breadth of social connection.",
        [("INFP", "dynorphin")] = "Dynorphin moderate — kappa-opioid social satiation signaling after group exposure drives withdrawal to restore internal coherence. KOR activation dampens residual social dopamine in hippocampal-PFC circuits, enabling default mode network re-engagement for self-referential values-processing. Precuneus introspective consolidation requires KOR-mediated clearing of interpersonal processing load. Social fatigue redirects energy toward solitary cognitive recharge and identity-narrative reconstruction.",
        [("INFP", "gaba")] = "GABA low-moderate — reduced fast inhibition allows emotional openness and sensitivity. Not strongly gated — feelings flow freely into awareness.",
        [("INFP", "adrenaline")] = "Adrenaline low — minimal sympathetic arousal. Conflict triggers withdrawal, not fight-or-flight activation. Beta-adrenergic tone subdued — gentle presence.",
        [("INFP", "crh")] = "CRH low — CRHR1 minimal. No closure-seeking from interpersonal ambiguity. Comfortable leaving conflicts unresolved — avoidance over confrontation.",
        [("INFP", "dhea")] = "DHEA moderate — buffers minimal cortisol to support creative flexibility. DHEA:cortisol ratio high — resilience through adaptability rather than structure.",
        [("INFP", "estradiol")] = "Estradiol moderate — ERalpha in hippocampus supports emotional memory encoding and empathic sensitivity. Affiliative warmth expressed through values-depth.",
        [("INFP", "glutamate")] = "Glutamate low-moderate — NMDA activity supports creative ideation without analytical rigor. Associative fluidity for metaphorical meaning-making.",
        [("INFP", "norepinephrine")] = "Norepinephrine low — locus coeruleus tone subdued. Alert to internal emotional states, not external threats. Defocused inward attention.",
        [("INFP", "npy")] = "NPY elevated — Y1/Y2 amygdala buffering eliminates anxiety from unstructured experience. Comfortable with ambiguity and organic flow.",
        [("INFP", "orexin")] = "Orexin low — OX1R exploration drive minimal. Prefers internal imaginative world over external novelty-seeking. Contemplative over active.",
        [("INFP", "oxytocin_h")] = "Hormonal oxytocin selective — hypothalamic paraventricular release suppressed outside deeply authentic intimate contexts, preserving solitary processing depth. Cognitive autonomy maintained — dorsomedial PFC and hippocampal self-referential circuits protected from broad social approach signaling. Internal processing protected from affiliative interrupt. Bonding through shared values and emotional vulnerability preserves introspective consolidation capacity.",
        [("INFP", "progesterone")] = "Progesterone moderate — allopregnanolone GABA-A modulation provides subtle calming without emotional constraint. Gentle stabilization for sensitive emotional processing.",
        [("INFP", "prolactin")] = "Prolactin moderate — tuberoinfundibular activation supports empathic caregiving in intimate contexts. Nurturing through emotional presence and values-support.",
        [("INFP", "substance_p")] = "Substance P moderate — NK1 receptor activation sensitive. Emotional distress signaling intact — high sensitivity to emotional pain and moral-values violations.",
        [("INFP", "testosterone")] = "Testosterone low — androgen effects minimal. No competitive or dominance drive. Influence through authenticity and values-depth, not assertion.",
        [("INFP", "thyroid")] = "Thyroid low-moderate — T3/T4 HPT axis supports sustained reflective processing without high-energy output. Metabolic pattern favors contemplation over action.",
        [("INFP", "vasopressin")] = "Vasopressin low-moderate — V1a pair-bonding selective and values-based. Deep loyalty to few. No territorial social enforcement — gentle boundary maintenance.",

        // ══════════════════════════════════════════════════════════════
        // ENFJ — The Protagonist
        // ══════════════════════════════════════════════════════════════
        [("ENFJ", "dopamine")] = "Dopamine elevated — D1 Gs-coupled phasic firing in mesolimbic pathway rewards social leadership and influence. VTA activation strongest when inspiring or facilitating others' growth. Social achievement dopamine — helping others succeed is the reward signal.",
        [("ENFJ", "serotonin")] = "Serotonin elevated — 5-HT1A receptor activation in dorsal raphe and anterior cingulate supports prosocial harm-aversion and values-driven moral judgment. High serotonin stabilizes social facilitation without impulsive action.",
        [("ENFJ", "norepinephrine")] = "Norepinephrine moderate — alpha-1 adrenergic arousal in social facilitation contexts. Phasic mode when orchestrating group dynamics. Alert to interpersonal undercurrents.",
        [("ENFJ", "gaba")] = "GABA moderate — GABA-A interneuron activity enables organized planful behavior in service of supporting others. Structure for people's benefit, not rigid control.",
        [("ENFJ", "estradiol")] = "Estradiol elevated — ERalpha receptor activation in hippocampus and amygdala enhances verbal fluency and social-emotional memory encoding. Empathy facilitation via estrogen-upregulated TPH2 serotonin synthesis.",
        [("ENFJ", "cortisol")] = "Cortisol moderate — GR-mediated response in PFC drives closure on interpersonal ambiguity. CRH cascade activates when social harmony is threatened. Acute cortisol enhances social memory consolidation.",
        [("ENFJ", "prolactin")] = "Prolactin elevated — tuberoinfundibular pathway D2 receptor disinhibition drives nurturing satisfaction and caregiving motivation. Prolactin release from genuine social connection reinforces helping behavior.",
        [("ENFJ", "oxytocin")] = "Oxytocin elevated — powerful affiliative cascade through OXTR upregulation in anterior insula and ventral striatum drives interpersonal synchrony and group belonging as primary reward signal. Mirror neuron facilitation of empathic attunement through temporoparietal junction social cognition. Ventromedial PFC social reward prediction maximizes during group facilitation. Social energy amplification through affiliative drive — high OXTR density in interpersonal reward circuits is the core group synchronization trait.",
        [("ENFJ", "oxytocin_h")] = "Hormonal oxytocin elevated — hypothalamic surge in group facilitation contexts amplifies social approach and group synchronization drive at maximum intensity. Ventral striatum affiliative energy generation during interpersonal coordination — anterior insula empathic attunement heightened for group orchestration. Social approach through group reward cascade activation — drives the social-connector phenotype through interpersonal synchrony.",
        [("ENFJ", "endorphins")] = "Endorphins elevated — strong social bonding endorphin cascade with mu-opioid reward from group laughter, shared experience, and interpersonal togetherness. Ventral striatum activation during social facilitation reinforces helping behavior — social network size correlates with endorphin function. Anterior insula interpersonal reward from shared growth. Group reward cascade from empathic connection, not solitary contemplative processing.",
        [("ENFJ", "vasopressin")] = "Vasopressin moderate — V1a pair-bonding extends to group loyalty and community structure maintenance. Vigilance in protecting social harmony.",
        [("ENFJ", "acetylcholine")] = "Acetylcholine moderate — muscarinic activation supports organized facilitation and attentional focus on group dynamics. Cholinergic attention for interpersonal orchestration.",
        [("ENFJ", "adrenaline")] = "Adrenaline moderate — beta-adrenergic arousal during social leadership and group facilitation. Sympathetic activation enhances performance in interpersonal coordination.",
        [("ENFJ", "bdnf")] = "BDNF elevated — TrkB signaling supports learning social-emotional patterns and adapting leadership strategies. Neuroplasticity for understanding diverse individuals.",
        [("ENFJ", "crh")] = "CRH moderate — CRHR1 drives closure on social disharmony. Physiological cost from interpersonal conflict mobilizes resolution behavior.",
        [("ENFJ", "dhea")] = "DHEA moderate — buffers cortisol to maintain warm engagement under social stress. DHEA:cortisol ratio supports resilient empathy without burnout.",
        [("ENFJ", "dynorphin")] = "Dynorphin low — minimal social fatigue signal as KOR social satiation absent in ventral striatum group reward circuits. Unlimited group engagement capacity for facilitation — no withdrawal drive from interpersonal interaction. Anterior insula and temporoparietal junction empathic processing sustained without kappa-opioid dampening. Social energy amplification through affiliative drive continues indefinitely — group synchronization maintains ventromedial PFC activation without depletion.",
        [("ENFJ", "endocannabinoid")] = "Endocannabinoid low-moderate — CB1 flexibility for adapting to diverse individuals but within structured supportive framework. Strategic adaptability for others' benefit.",
        [("ENFJ", "enkephalins")] = "Enkephalins moderate — delta-opioid hedonic reward from social play and interpersonal warmth during group facilitation. DOR activation in ventral striatum during group activities and shared joy of helping others grow. Contentment from social connection and belonging through empathic coordination — ventromedial PFC social reward prediction reinforces group harmony-seeking. Pleasure from interpersonal synchrony, not from solitary aesthetic experience.",
        [("ENFJ", "glutamate")] = "Glutamate moderate — NMDA activity supports social pattern recognition and strategic interpersonal planning. Enough excitation for dynamic facilitation without analytical coldness.",
        [("ENFJ", "melatonin")] = "Melatonin low-moderate — suppressed circadian gating as ventral striatum social reward cascades from group facilitation override pineal onset signals. Sympathetic engagement extends into evening — anterior insula and temporoparietal junction interpersonal attunement circuits remain active during group orchestration. Social arousal preventing melatonin onset through ventromedial PFC affiliative drive that sustains empathic group engagement. Interpersonal energy amplification delays circadian transition.",
        [("ENFJ", "npy")] = "NPY moderate — Y1/Y2 buffering provides stress resilience for handling others' emotional distress without personal overwhelm. Anxiety reduction supports steady caregiving.",
        [("ENFJ", "orexin")] = "Orexin moderate — OX2R activation during social leadership and group orchestration. Exploration drive for social connection and influence opportunities.",
        [("ENFJ", "progesterone")] = "Progesterone moderate — allopregnanolone GABA-A modulation provides emotional steadiness for nurturing leadership. Calming stability in service of others.",
        [("ENFJ", "substance_p")] = "Substance P moderate — NK1 receptor activation sensitive to others' distress. Empathic pain signaling drives helping behavior. High sensitivity to social-emotional suffering.",
        [("ENFJ", "testosterone")] = "Testosterone low-moderate — androgen effects minimal. Leadership through empathy and inspiration, not dominance or assertion. Influence without aggression.",
        [("ENFJ", "thyroid")] = "Thyroid moderate-high — T3/T4 supports sustained high-energy social facilitation. HPT axis fuels relentless interpersonal engagement and group orchestration.",

        // ══════════════════════════════════════════════════════════════
        // ENFP — The Campaigner
        // ══════════════════════════════════════════════════════════════
        [("ENFP", "dopamine")] = "Dopamine elevated — D1/D2 phasic burst firing in VTA-NAc mesolimbic pathway strongly amplified by social context. Novelty-seeking prediction errors maximized during interpersonal idea exchange. High dopamine with low serotonin and low GABA — unbraked enthusiastic exploration.",
        [("ENFP", "endocannabinoid")] = "Endocannabinoid elevated — 2-AG CB1 retrograde signaling provides flexibility and spontaneity. Resists premature closure and rigid scheduling. Anandamide supports present-moment flow during social exploration.",
        [("ENFP", "gaba")] = "GABA low — GABA-A frontal inhibition reduced. Disinhibited emotional expression and spontaneous verbal output. Low GABA with high dopamine — expressive and uninhibited social energy.",
        [("ENFP", "serotonin")] = "Serotonin low — 5-HT2A in DMN supports abstract future-possibility visualization but low tonic 5-HT — no premature satisfaction or routine-seeking. Always reaching for the next exciting possibility.",
        [("ENFP", "cortisol")] = "Cortisol low — minimal GR-mediated anxiety from unstructured situations. Low diurnal amplitude — ambiguity is not stressful but exciting.",
        [("ENFP", "oxytocin")] = "Oxytocin elevated — powerful affiliative cascade through OXTR upregulation in anterior insula and ventral striatum drives interpersonal synchrony with diverse partners. Group belonging as primary reward signal — mirror neuron facilitation of empathic connection through temporoparietal junction social cognition. Ventromedial PFC social reward prediction maximizes during novel interpersonal encounter. Social energy amplification through broad affiliative drive — approach motivation toward group connection as default mode.",
        [("ENFP", "oxytocin_h")] = "Hormonal oxytocin elevated — hypothalamic surge in group contexts amplifies social approach and group synchronization drive broadly. Ventral striatum affiliative energy generation during interpersonal exploration — anterior insula empathic attunement heightened for warm connection with diverse partners. Social approach through group reward cascade activation — interpersonal synchrony drive toward everyone as potential connection.",
        [("ENFP", "bdnf")] = "BDNF elevated — TrkB signaling supports creative ideation and rapid associative pattern formation across domains. Ideas spark ideas.",
        [("ENFP", "orexin")] = "Orexin elevated — OX2R in lateral hypothalamus drives spontaneous exploration in social contexts. Fires during play, novelty, and conversational discovery.",
        [("ENFP", "endorphins")] = "Endorphins elevated — strong social bonding endorphin cascade with mu-opioid reward from group laughter, shared enthusiasm, and physical interpersonal togetherness. Ventral striatum activation during social play reinforces connection-seeking — social network size correlates with endorphin function. Anterior insula interpersonal reward from shared excitement and possibility. Group reward cascade from collaborative enthusiasm, not solitary contemplative processing.",
        [("ENFP", "enkephalins")] = "Enkephalins moderate — delta-opioid hedonic reward from social play and interpersonal warmth during enthusiastic group exploration. DOR activation in ventral striatum during group activities and shared joy of discovery. Contentment from social connection and belonging through variety-seeking interpersonal engagement — ventromedial PFC social reward prediction reinforces group play-seeking. Pleasure from interpersonal synchrony, not from solitary contemplation.",
        [("ENFP", "acetylcholine")] = "Acetylcholine low-moderate — muscarinic deep-processing minimal. Parasympathetic reflective circuits deprioritized. Present-moment social energy over contemplative depth.",
        [("ENFP", "adrenaline")] = "Adrenaline moderate — beta-adrenergic arousal during social novelty and exciting possibilities. Sympathetic activation enhances enthusiastic expression.",
        [("ENFP", "crh")] = "CRH low — CRHR1 minimal. No closure-seeking from open-ended social exploration. Ambiguity is exciting, not costly.",
        [("ENFP", "dhea")] = "DHEA elevated — high DHEA:cortisol ratio eliminates anxiety from unstructured situations. Neurosteroid buffering supports perpetual optimistic exploration.",
        [("ENFP", "dynorphin")] = "Dynorphin low — minimal social fatigue signal as KOR social satiation absent in ventral striatum group reward circuits. Unlimited group engagement capacity for enthusiastic interpersonal exploration — no withdrawal drive from social interaction. Anterior insula and temporoparietal junction social-emotional processing sustained without kappa-opioid dampening. Social energy amplification continues indefinitely — group synchronization maintains ventromedial PFC activation without depletion.",
        [("ENFP", "estradiol")] = "Estradiol moderate — ERalpha enhances verbal fluency and empathic social warmth. Affiliative expression through enthusiastic connection.",
        [("ENFP", "glutamate")] = "Glutamate moderate — NMDA supports rapid associative ideation across social contexts. Cognitive flexibility for creative interpersonal pattern-making.",
        [("ENFP", "melatonin")] = "Melatonin low — suppressed circadian gating as ventral striatum social reward cascades from interpersonal exploration override pineal onset signals. Sympathetic engagement extends into evening — anterior insula and temporoparietal junction social-emotional circuits remain active during group connection. Social arousal preventing melatonin onset through ventromedial PFC affiliative drive that sustains enthusiastic interpersonal engagement. Group energy amplification delays circadian transition indefinitely.",
        [("ENFP", "norepinephrine")] = "Norepinephrine moderate — locus coeruleus tonic mode for broad scanning attention in social contexts. Alert to novel interpersonal possibilities.",
        [("ENFP", "npy")] = "NPY elevated — Y1/Y2 amygdala buffering eliminates anxiety from uncertainty. Comfortable with spontaneous unplanned social exploration.",
        [("ENFP", "progesterone")] = "Progesterone low — allopregnanolone minimal. No emotional calming constraint on enthusiastic expression. Uninhibited warmth without stabilization.",
        [("ENFP", "prolactin")] = "Prolactin low-moderate — nurturing through enthusiastic support and possibility-generation, not through structure or caregiving routine.",
        [("ENFP", "substance_p")] = "Substance P low-moderate — NK1 receptor activation subdued. Emotional resilience — bounces back quickly from social disappointment.",
        [("ENFP", "testosterone")] = "Testosterone low-moderate — androgen effects minimal. Social influence through charm and enthusiasm, not dominance or assertion.",
        [("ENFP", "thyroid")] = "Thyroid moderate-high — T3/T4 supports high-energy spontaneous social engagement. HPT axis fuels relentless enthusiastic interaction.",
        [("ENFP", "vasopressin")] = "Vasopressin low — V1a bonding broad and diffuse. Warm connection with many, loyalty expressed through possibility-sharing rather than territorial protection.",

        // ══════════════════════════════════════════════════════════════
        // ISTJ — The Logistician
        // ══════════════════════════════════════════════════════════════
        [("ISTJ", "gaba")] = "GABA elevated — GABA-A chloride conductance in prefrontal cortex and anterior cingulate creates powerful behavioral inhibition and impulse suppression. Interneuron gating enforces methodical sequential execution. Tonic inhibition dominant — reliable, consistent behavioral patterns.",
        [("ISTJ", "serotonin")] = "Serotonin elevated — 5-HT1A/5-HT2A receptor balance in dorsal raphe maintains routine stability and sensory-present focus. Exploitation over exploration dominance via 5-HT2C inhibition of VTA dopamine novelty signals. Present-moment concrete processing.",
        [("ISTJ", "acetylcholine")] = "Acetylcholine moderate — nicotinic alpha-4-beta-2 receptor activation in basal forebrain drives high signal-to-noise sensory discrimination and detail-oriented concrete processing. Focused on what IS not what could be.",
        [("ISTJ", "dopamine")] = "Dopamine low — D2 receptor novelty sensitivity in ventral striatum attenuated. Phasic prediction-error signals reduced — minimal exploration impulse. Tonic stability over phasic novelty. Proven methods over innovation.",
        [("ISTJ", "cortisol")] = "Cortisol moderate — GR-mediated response in hippocampus triggers immediate corrective action when disorder detected. CRH CRHR1 activation from ambiguity drives structure-imposition. Acute cortisol sharpens procedural attention.",
        [("ISTJ", "vasopressin")] = "Vasopressin elevated — V1a receptor in lateral septum enforces territorial boundaries and precedent-based consistency. Familiarity recognition over novelty. Memory consolidation for routines.",
        [("ISTJ", "endocannabinoid")] = "Endocannabinoid low — minimal CB1 flexibility. Habitual response patterns dominate over adaptive switching. Structure is comfortable, improvisation is costly.",
        [("ISTJ", "orexin")] = "Orexin low — OX1R/OX2R exploration drive minimal. Lateral hypothalamus activation only in familiar task contexts, not during novel exploration.",
        [("ISTJ", "melatonin")] = "Melatonin moderate — SCN-mediated circadian withdrawal signaling supports parasympathetic restoration through predictable pineal-driven solitude cycles. MT1/MT2 receptor regularity in suprachiasmatic nucleus enforces neural quieting on consistent schedule. Default mode network consolidation during evening withdrawal enables introspective processing of procedural knowledge. Cognitive recharge through solitary routine — circadian discipline serves internal coherence maintenance.",
        [("ISTJ", "crh")] = "CRH moderate — CRHR1 activation from deviation drives correction back to established standards. Ambiguity creates physiological cost that structure resolves.",
        [("ISTJ", "adrenaline")] = "Adrenaline low — minimal sympathetic arousal. Calm steady execution without fight-or-flight activation. Beta-adrenergic tone subdued — methodical not reactive.",
        [("ISTJ", "bdnf")] = "BDNF low-moderate — TrkB signaling subdued. Neuroplasticity limited — prefers proven methods over continuous learning. Stability over adaptation.",
        [("ISTJ", "dhea")] = "DHEA low-moderate — DHEA:cortisol ratio balanced toward structure-seeking. Minimal buffering allows cortisol closure-drive to motivate order-imposition.",
        [("ISTJ", "dynorphin")] = "Dynorphin moderate — kappa-opioid social satiation signaling after group exposure drives withdrawal to restore internal coherence through familiar solitary routines. KOR activation dampens residual social dopamine in hippocampal-PFC circuits, enabling default mode network re-engagement for procedural consolidation. Precuneus self-referential processing requires KOR-mediated clearing of interpersonal load. Social fatigue redirects energy toward solitary cognitive recharge within established structures.",
        [("ISTJ", "endorphins")] = "Endorphins low — mu-opioid reward from solitary mastery and procedural completion rather than interpersonal warmth. Periaqueductal gray activation from cognitive closure of task-sequences during deep focus. Beta-endorphin release tied to hippocampal consolidation of established standards — solitary processing depth generates opioid reinforcement from duty fulfillment independent of social network engagement.",
        [("ISTJ", "enkephalins")] = "Enkephalins low — delta-opioid hedonic reward from solitary contemplative completion of procedural tasks. DOR activation in hippocampal-PFC circuits during methodical internal processing provides quiet contentment from cognitive mastery of established systems. Pleasure derived from introspective consolidation of duty-knowledge and orderly execution, not from interpersonal warmth or group play.",
        [("ISTJ", "estradiol")] = "Estradiol low — ERalpha effects minimal. No affiliative empathic expression drive. Cognitive focus without social-emotional warmth.",
        [("ISTJ", "glutamate")] = "Glutamate moderate — NMDA supports procedural memory consolidation and detail-oriented processing. Excitation for concrete problem-solving without creative divergence.",
        [("ISTJ", "norepinephrine")] = "Norepinephrine low-moderate — locus coeruleus phasic mode for selective attention to concrete details. Alert to deviations from standards without hypervigilance.",
        [("ISTJ", "npy")] = "NPY low-moderate — Y1/Y2 amygdala buffering minimal. Ambiguity creates anxiety that motivates structure-seeking. Low tolerance for uncertainty.",
        [("ISTJ", "oxytocin")] = "Oxytocin low — OXTR downregulation in hippocampal and dorsomedial PFC self-referential circuits minimizes affiliative signaling interference with procedural internal model construction. Self-referential processing dominance preserves cognitive autonomy — default mode network consolidation of duty-knowledge operates without peptidergic bonding modulation. Internal model fidelity of established standards prioritized over social consensus. Service expressed through reliable solitary execution, not through affiliative warmth.",
        [("ISTJ", "oxytocin_h")] = "Hormonal oxytocin low — hypothalamic paraventricular release minimal, preserving solitary processing depth from social approach interrupts. Cognitive autonomy maintained — dorsomedial PFC self-referential circuits protected from hypothalamic affiliative signaling. Internal processing of procedural standards undisturbed by social drive. Interaction functional and duty-based, preserving introspective consolidation capacity.",
        [("ISTJ", "progesterone")] = "Progesterone low-moderate — allopregnanolone provides subtle stabilization without warmth. Calm execution of responsibilities.",
        [("ISTJ", "prolactin")] = "Prolactin low — tuberoinfundibular D2 inhibition strong. Minimal nurturing satisfaction. Duty over caregiving warmth.",
        [("ISTJ", "substance_p")] = "Substance P low — NK1 receptor minimal. High pain tolerance. Emotional distress does not interfere with procedural execution.",
        [("ISTJ", "testosterone")] = "Testosterone low-moderate — androgen effects support analytical focus without dominance drive. Competence over competition.",
        [("ISTJ", "thyroid")] = "Thyroid moderate — T3/T4 supports steady reliable metabolism. HPT axis provides consistent energy for methodical task completion without hyperarousal.",

        // ══════════════════════════════════════════════════════════════
        // ISFJ — The Defender
        // ══════════════════════════════════════════════════════════════
        [("ISFJ", "serotonin")] = "Serotonin elevated — 5-HT1A tonic activation in dorsal raphe and limbic circuits provides emotional stability and prosocial harm-aversion. Strong bias toward duty-driven caregiving behavior. Moderate serotonin with low dopamine — passive contentment in service.",
        [("ISFJ", "gaba")] = "GABA elevated — GABA-A interneuron inhibitory tone in amygdala and PFC creates calm measured responding under interpersonal stress. High GABA with low cortisol — calm safety in familiar caregiving.",
        [("ISFJ", "acetylcholine")] = "Acetylcholine elevated — nicotinic and muscarinic receptor activation in hippocampus enhances episodic memory encoding for specific details about others' needs. High signal-to-noise for changes in familiar environments.",
        [("ISFJ", "dopamine")] = "Dopamine low — D1/D2 novelty drive in mesocortical pathway subdued. Stable internal reward from consistent service over novel experience. Not seeking stimulation.",
        [("ISFJ", "cortisol")] = "Cortisol moderate — HPA axis response specifically to routine disruption. GR activation drives preservation of established caregiving patterns. Anxiety targeted to deviation from the familiar, not generalized.",
        [("ISFJ", "progesterone")] = "Progesterone elevated — allopregnanolone GABA-A positive allosteric modulation provides neuroprotective calming stability and emotional steadiness. GABA potentiation creates quiet reliable presence.",
        [("ISFJ", "prolactin")] = "Prolactin elevated — tuberoinfundibular pathway activation supports nurturing satisfaction and emotional attunement to dependent others' distress signals.",
        [("ISFJ", "oxytocin")] = "Oxytocin low — OXTR downregulation across ventral striatum and anterior insula group reward circuits minimizes affiliative approach signaling and crowd-seeking drive. Hippocampal and dorsomedial PFC self-referential circuits monopolize processing bandwidth — internal model construction of familiar others through default mode network simulation operates without peptidergic social interrupt. Precuneus introspective loops consolidate episodic memories in hermit-mode solitary recharge rather than through group synchronization. Social consensus seeking absent — cognitive autonomy preserved from oxytocin-mediated crowd engagement.",
        [("ISFJ", "endorphins")] = "Endorphins low — mu-opioid reward from solitary mastery and internal contemplative processing rather than interpersonal warmth or group togetherness. Periaqueductal gray activation from cognitive completion events during deep solitary focus — hippocampal pattern-completion of episodic memories in quiet isolation. Beta-endorphin release tied to introspective consolidation depth in hermit-mode recharge, not from social network engagement or crowd-based affiliative warmth. Solitary processing generates its own opioid reinforcement independent of group context.",
        [("ISFJ", "vasopressin")] = "Vasopressin moderate — V1a pair-bonding and loyalty to family and close community. Protective vigilance for those in care.",
        [("ISFJ", "adrenaline")] = "Adrenaline low — minimal sympathetic arousal. Calm caregiving presence without fight-or-flight reactivity. Beta-adrenergic tone subdued — steady not urgent.",
        [("ISFJ", "bdnf")] = "BDNF low-moderate — TrkB signaling limited. Neuroplasticity for familiar role refinement, not novel pattern generation. Stability in caregiving over innovation.",
        [("ISFJ", "crh")] = "CRH moderate — CRHR1 activation from disruption to established caregiving routines. Anxiety drives restoration of familiar supportive patterns.",
        [("ISFJ", "dhea")] = "DHEA low-moderate — minimal cortisol buffering. DHEA:cortisol ratio balanced toward structure-seeking in caregiving contexts.",
        [("ISFJ", "dynorphin")] = "Dynorphin elevated — kappa-opioid receptor social satiation signaling powerfully activated after group exposure generates strong biological shutdown of external engagement. KOR Gi-coupled aversive signaling creates intense social fatigue after crowd interaction — PV+ interneuron networks actively suppress social approach circuits in ventral striatum. Deep solitary withdrawal to restore internal coherence through hermit-mode recharge in familiar quiet environment. Precuneus and dorsomedial PFC default mode re-engagement requires KOR-mediated clearing of interpersonal processing load — social noise experienced as metabolically costly intrusion on peaceful self-referential consolidation.",
        [("ISFJ", "endocannabinoid")] = "Endocannabinoid low — CB1 flexibility minimal. Established caregiving routines dominate. Improvisation limited to familiar supportive contexts.",
        [("ISFJ", "enkephalins")] = "Enkephalins low — delta-opioid hedonic reward from solitary contemplative processing and quiet internal reflection. DOR activation in hippocampal-PFC circuits during introspective consolidation of episodic memories in complete social isolation. Quiet contentment from cognitive mastery in hermit-mode solitary depth — pleasure derived from peaceful self-referential processing and internal model refinement, not from interpersonal warmth, group play, or crowd-based social reward.",
        [("ISFJ", "estradiol")] = "Estradiol moderate — ERalpha enhances social-emotional memory for others' needs and empathic caregiving expression. Affiliative warmth through practical support.",
        [("ISFJ", "glutamate")] = "Glutamate low-moderate — NMDA supports episodic memory encoding for caregiving details without analytical abstraction. Concrete interpersonal focus.",
        [("ISFJ", "melatonin")] = "Melatonin elevated — SCN-mediated circadian withdrawal signaling drives deep parasympathetic restoration through pineal-driven hermit-mode solitude cycles. MT1/MT2 receptor hypersensitivity in suprachiasmatic nucleus orchestrates aggressive neural quieting and default mode network consolidation during evening withdrawal into complete social isolation. Dorsomedial PFC and precuneus self-referential processing deepens as task-positive social circuits shut down entirely. High melatonin with cognitive autonomy preference — solitary circadian recharge in quiet familiar environment fuels internal coherence rather than social engagement.",
        [("ISFJ", "norepinephrine")] = "Norepinephrine low-moderate — locus coeruleus tone alert to changes in familiar others' needs without hypervigilance. Selective attention for caregiving cues.",
        [("ISFJ", "npy")] = "NPY low-moderate — Y1/Y2 buffering minimal. Disruption to routine creates anxiety. Comfort in familiar caregiving patterns.",
        [("ISFJ", "orexin")] = "Orexin low — OX1R exploration drive minimal. Arousal for caregiving tasks in familiar contexts, not for novelty-seeking.",
        [("ISFJ", "oxytocin_h")] = "Hormonal oxytocin low — hypothalamic paraventricular release minimal, protecting solitary processing depth from social approach interrupts. Group contexts impose severe metabolic cost on internal coherence — dorsomedial PFC self-referential circuits require isolation from hypothalamic affiliative signaling to maintain episodic memory consolidation. Crowd exposure triggers rapid depletion of introspective consolidation capacity. One-on-one familiar interaction preserves cognitive autonomy — group synchronization drive biologically suppressed.",
        [("ISFJ", "substance_p")] = "Substance P moderate — NK1 receptor sensitive to others' distress. Empathic pain signaling drives nurturing response. High sensitivity to dependent others' suffering.",
        [("ISFJ", "testosterone")] = "Testosterone low — androgen effects minimal. Caregiving through gentle support, not assertion or dominance. Nurturing over competing.",
        [("ISFJ", "thyroid")] = "Thyroid moderate — T3/T4 supports steady caregiving metabolism. HPT axis provides consistent energy for reliable supportive presence without agitation.",

        // ══════════════════════════════════════════════════════════════
        // ESTJ — The Executive
        // ══════════════════════════════════════════════════════════════
        [("ESTJ", "dopamine")] = "Dopamine elevated — phasic burst firing in VTA-NAc mesolimbic pathway rewards social achievement, status acquisition, and efficient resource organization. D1 Gs-coupled in PFC supports rapid procedural execution.",
        [("ESTJ", "norepinephrine")] = "Norepinephrine elevated — beta-adrenergic receptor arousal in locus coeruleus amplifies assertive executive function during group coordination. Phasic mode for decisive action under operational demands.",
        [("ESTJ", "serotonin")] = "Serotonin elevated — 5-HT2A in dorsal raphe maintains order and rule adherence. 5-HT2C inhibition of VTA dopamine creates exploitation-over-exploration bias. Proven methods over innovation. High serotonin with high dopamine — energized orderliness.",
        [("ESTJ", "gaba")] = "GABA elevated — GABA-A interneuron gating in anterior cingulate enforces boundary maintenance and rule compliance. Impulse suppression in service of organizational standards.",
        [("ESTJ", "testosterone")] = "Testosterone elevated — androgen receptor activation in amygdala and PFC potentiates social dominance, assertiveness, and organizational command. Hypothalamic-pituitary-gonadal axis active.",
        [("ESTJ", "cortisol")] = "Cortisol moderate — GR-mediated PFC enhancement channels stress into structured hierarchical control. HPA axis activation drives immediate problem-resolution through established procedures.",
        [("ESTJ", "adrenaline")] = "Adrenaline moderate — beta-adrenergic acute activation supports decisive action under operational pressure.",
        [("ESTJ", "vasopressin")] = "Vasopressin elevated — V1a receptor in lateral septum and ventral pallidum drives territorial hierarchy maintenance and precedent enforcement.",
        [("ESTJ", "endocannabinoid")] = "Endocannabinoid low — minimal CB1 flexibility. Proven approaches and standard operating procedures dominate over adaptive improvisation.",
        [("ESTJ", "oxytocin")] = "Oxytocin moderate — OXTR upregulation in anterior insula and ventral striatum amplifies interpersonal synchrony drive in task-oriented group coordination. Group belonging as reward signal through shared organizational achievement — mirror neuron facilitation of team alignment through temporoparietal junction social cognition. Ventromedial PFC social reward prediction during hierarchical group management. Affiliative cascade through shared work and group status signaling.",
        [("ESTJ", "crh")] = "CRH moderate — CRHR1 drives structured response to organizational disruption. Low tolerance for chaos.",
        [("ESTJ", "acetylcholine")] = "Acetylcholine moderate — muscarinic activation supports organized procedural execution and attention to operational details. Cholinergic focus for efficient coordination.",
        [("ESTJ", "bdnf")] = "BDNF low-moderate — TrkB signaling limited. Neuroplasticity for refining proven methods, not for innovative exploration. Stability in procedures.",
        [("ESTJ", "dhea")] = "DHEA moderate — buffers cortisol to maintain assertive confidence under operational pressure. DHEA:cortisol ratio supports decisive action without anxiety.",
        [("ESTJ", "dynorphin")] = "Dynorphin low — minimal social fatigue signal as KOR social satiation absent in ventral striatum group reward circuits during organizational achievement. Unlimited group engagement capacity for hierarchical coordination — no withdrawal drive from team interaction. Anterior insula and temporoparietal junction management-processing sustained without kappa-opioid dampening. Social energy amplification through organizational command continues indefinitely without depletion signal.",
        [("ESTJ", "endorphins")] = "Endorphins low-moderate — mu-opioid reward from group achievement cascade and shared organizational success rather than solitary mastery. Ventral striatum activation during team task-completion reinforces hierarchical engagement — social network of direct reports correlates with endorphin function. Anterior insula interpersonal reward from efficient group coordination. Group reward cascade from organizational execution, not contemplative processing depth.",
        [("ESTJ", "enkephalins")] = "Enkephalins low — delta-opioid hedonic reward from group activities and shared organizational achievement. DOR activation in ventral striatum during interpersonal coordination success — contentment from social connection through hierarchical group management. Ventromedial PFC social reward prediction reinforces group status signaling. Pleasure from interpersonal organizational synchrony, not from solitary aesthetic experience.",
        [("ESTJ", "estradiol")] = "Estradiol low — ERalpha effects minimal. Leadership through authority and efficiency, not empathic warmth. Cognitive focus without affiliative expression.",
        [("ESTJ", "glutamate")] = "Glutamate elevated — NMDA/AMPA fast excitatory transmission in PFC supports rapid procedural decision-making and organizational pattern execution.",
        [("ESTJ", "melatonin")] = "Melatonin low-moderate — suppressed circadian gating as ventral striatum social reward from organizational coordination overrides pineal onset signals. Sympathetic engagement extends into evening — anterior insula and temporoparietal junction group-management circuits remain active during hierarchical oversight. Social arousal preventing melatonin onset through ventromedial PFC group status signaling that sustains operational team engagement. Interpersonal energy from organizational command delays circadian transition.",
        [("ESTJ", "npy")] = "NPY low-moderate — Y1/Y2 buffering minimal. Organizational disruption creates anxiety that drives immediate corrective action.",
        [("ESTJ", "orexin")] = "Orexin moderate — OX1R activation during organizational challenge and resource optimization. Arousal for efficient execution, not exploratory novelty.",
        [("ESTJ", "oxytocin_h")] = "Hormonal oxytocin moderate — hypothalamic surge in group coordination contexts amplifies social approach and group synchronization drive for organizational objectives. Ventral striatum affiliative energy generation during team-based task execution — anterior insula interpersonal attunement heightened for hierarchical coordination. Social approach through group reward cascade activation in work contexts.",
        [("ESTJ", "progesterone")] = "Progesterone low — allopregnanolone minimal. No emotional softening. Assertive decisive execution without warmth buffering.",
        [("ESTJ", "prolactin")] = "Prolactin low — tuberoinfundibular D2 inhibition strong. Minimal nurturing satisfaction. Leadership through command and efficiency, not caregiving.",
        [("ESTJ", "substance_p")] = "Substance P low — NK1 receptor minimal. High pain tolerance. Emotional distress does not interfere with organizational execution.",
        [("ESTJ", "thyroid")] = "Thyroid elevated — T3/T4 HPT axis high. Metabolic drive supports sustained high-energy organizational execution and assertive action.",

        // ══════════════════════════════════════════════════════════════
        // ESFJ — The Consul
        // ══════════════════════════════════════════════════════════════
        [("ESFJ", "serotonin")] = "Serotonin elevated — 5-HT1A/5-HT2A receptor activation in dorsal raphe and anterior cingulate supports prosocial harmony-maintenance and harm-aversion. Strong moral-emotional judgment favoring group cohesion.",
        [("ESFJ", "dopamine")] = "Dopamine moderate — D1 phasic firing in mesolimbic pathway rewards social approval, belonging, and community-building achievement. Social status via warmth and helpfulness, not dominance.",
        [("ESFJ", "gaba")] = "GABA moderate — GABA-A frontal interneuron activity stabilizes emotional regulation during social coordination. Enough inhibition for organized nurturing without emotional overwhelm.",
        [("ESFJ", "estradiol")] = "Estradiol elevated — ERalpha/ERbeta receptor activation in hippocampus and PFC enhances social-emotional memory and verbal empathic expression. Estrogen upregulates TPH2 serotonin synthesis — compound prosocial effect.",
        [("ESFJ", "cortisol")] = "Cortisol moderate — GR-mediated PFC response drives closure on social disharmony. CRH CRHR1 activation when group cohesion is threatened — must fix the social rupture.",
        [("ESFJ", "prolactin")] = "Prolactin elevated — tuberoinfundibular D2 disinhibition drives nurturing satisfaction and caregiving motivation in community contexts.",
        [("ESFJ", "oxytocin")] = "Oxytocin elevated — powerful crowd-driven affiliative reward cascade through OXTR upregulation in anterior insula and ventral striatum codes group belonging as primary reward prediction signal. Mirror neuron facilitation of interpersonal synchrony across temporoparietal junction circuits during community gatherings, family events, and group coordination. Ventromedial PFC social reward prediction maximizes during large social assemblies — being surrounded by familiar community members generates peak OXTR activation. Social energy amplification through high-density affiliative drive — the more people present, the stronger the oxytocin cascade.",
        [("ESFJ", "oxytocin_h")] = "Hormonal oxytocin elevated — hypothalamic paraventricular surge in group contexts amplifies social approach drive at maximum intensity for crowd engagement and community gathering. Ventral striatum affiliative energy generation during team coordination, family events, and neighborhood organizing — anterior insula interpersonal attunement heightened for maintaining group synchronization across multiple simultaneous social relationships. Social approach for community connection through group reward cascade activation — marathon social sessions sustained without depletion.",
        [("ESFJ", "endorphins")] = "Endorphins elevated — strong crowd-driven social bonding endorphin cascade with mu-opioid reward from group laughter, family gatherings, community events, and physical interpersonal togetherness. NAc shell activation codes crowd presence as primary reward prediction signal — social network size of community connections correlates with endorphin function. Anterior insula interpersonal reward from being surrounded by familiar community members. Group reward cascade from party attendance and team collaboration, not solitary contemplative processing depth.",
        [("ESFJ", "enkephalins")] = "Enkephalins elevated — delta-opioid hedonic reward from crowd-based social play and interpersonal warmth during community rituals, traditions, and group celebrations. DOR activation in ventral striatum during group activities, family events, and shared joy of community belonging. Contentment from being the center of community engagement — ventromedial PFC social reward prediction reinforces group gathering attendance and team coordination. Pleasure from interpersonal synchrony during familiar social rituals, not from solitary contemplation or hermit-mode processing.",
        [("ESFJ", "vasopressin")] = "Vasopressin moderate — V1a loyalty to community and family structure.",
        [("ESFJ", "acetylcholine")] = "Acetylcholine moderate — muscarinic activation supports organized caregiving and attentional focus on others' practical needs. Cholinergic attention for interpersonal details.",
        [("ESFJ", "adrenaline")] = "Adrenaline moderate — beta-adrenergic arousal during social coordination and community organizing. Sympathetic activation enhances caregiving performance.",
        [("ESFJ", "bdnf")] = "BDNF moderate — TrkB signaling supports learning caregiving patterns and adapting to others' needs. Neuroplasticity for refining supportive routines.",
        [("ESFJ", "crh")] = "CRH moderate — CRHR1 activation from social disharmony. Physiological cost from interpersonal conflict drives restoration of group cohesion.",
        [("ESFJ", "dhea")] = "DHEA moderate — buffers cortisol to maintain warm engagement under social stress. DHEA:cortisol ratio supports resilient caregiving without burnout.",
        [("ESFJ", "dynorphin")] = "Dynorphin low — KOR social satiation signaling absent in ventral striatum group reward circuits — no biological shutdown of external engagement after crowd exposure. Fearless sustained group participation without withdrawal signal or social fatigue. Anterior insula and temporoparietal junction interpersonal processing sustained indefinitely without kappa-opioid dampening — marathon social sessions at community events, family gatherings, and team activities generate no depletion. Social energy amplification through crowd-driven affiliative reward continues without limit.",
        [("ESFJ", "endocannabinoid")] = "Endocannabinoid low — CB1 flexibility minimal. Established caregiving routines and social traditions dominate. Structure in service of community.",
        [("ESFJ", "glutamate")] = "Glutamate moderate — NMDA supports social pattern recognition and coordination planning. Excitation for organizing group activities without analytical detachment.",
        [("ESFJ", "melatonin")] = "Melatonin low — suppressed circadian gating as ventral striatum crowd-driven social reward cascades override pineal onset signals entirely. Sympathetic engagement extends deep into evening hours — anterior insula and temporoparietal junction interpersonal attunement circuits remain maximally active during community gatherings and group social events. Social arousal preventing melatonin onset through ventromedial PFC affiliative drive that sustains marathon group engagement. Community energy amplification from crowd presence delays parasympathetic transition indefinitely — the party continues as long as people are present.",
        [("ESFJ", "norepinephrine")] = "Norepinephrine moderate — locus coeruleus alert to community needs and interpersonal disruptions. Vigilance for social harmony maintenance.",
        [("ESFJ", "npy")] = "NPY moderate — Y1/Y2 buffering provides stress resilience for handling community stress without personal overwhelm. Anxiety reduction supports steady caregiving.",
        [("ESFJ", "orexin")] = "Orexin moderate — OX2R activation during community organizing and social facilitation. Arousal for caregiving coordination, not novelty exploration.",
        [("ESFJ", "progesterone")] = "Progesterone moderate — allopregnanolone GABA-A modulation provides emotional steadiness for nurturing community support. Calming stability for caregiving.",
        [("ESFJ", "substance_p")] = "Substance P moderate — NK1 receptor sensitive to others' distress. Empathic pain signaling drives community helping behavior. High sensitivity to social suffering.",
        [("ESFJ", "testosterone")] = "Testosterone low — androgen effects minimal. Community leadership through warmth and support, not dominance or assertion. Nurturing over competing.",
        [("ESFJ", "thyroid")] = "Thyroid moderate — T3/T4 supports sustained caregiving energy. HPT axis provides consistent metabolism for reliable community support without hyperarousal.",

        // ══════════════════════════════════════════════════════════════
        // ISTP — The Virtuoso
        // ══════════════════════════════════════════════════════════════
        [("ISTP", "acetylcholine")] = "Acetylcholine elevated — muscarinic M1 parasympathetic activation in PFC and sensorimotor cortex creates quiet focused attention on physical systems and mechanical interaction. Cholinergic tone for fine motor discrimination and hands-on problem solving.",
        [("ISTP", "norepinephrine")] = "Norepinephrine elevated — alpha-2A adrenergic receptor activation in locus coeruleus provides heightened sensory alertness for environmental input. Phasic mode for in-the-moment situational responsiveness. Alert to physical-spatial information.",
        [("ISTP", "endocannabinoid")] = "Endocannabinoid elevated — anandamide CB1 signaling in PFC supports adaptability and resistance to externally imposed structure. Flexible response to immediate environmental demands. Works in bursts, follows interest.",
        [("ISTP", "gaba")] = "GABA moderate — GABA-A in amygdala provides impulse management under operational pressure without emotional flooding. Calm under crisis. Not constraining — just stabilizing.",
        [("ISTP", "dopamine")] = "Dopamine moderate — D2 receptor activation in striatum provides reward from skillful execution rather than social achievement. Mesocortical not mesolimbic dominance. Tinkering satisfaction.",
        [("ISTP", "serotonin")] = "Serotonin low — minimal 5-HT1A tonic activity in dorsal raphe. No routine adherence or structure-seeking. Low serotonin with high norepinephrine — alert adaptability without behavioral constraint.",
        [("ISTP", "testosterone")] = "Testosterone moderate — androgen receptor activation in PFC enhances analytical detachment and spatial-mechanical reasoning without social dominance motivation. Systemizing through hands-on interaction.",
        [("ISTP", "adrenaline")] = "Adrenaline moderate — beta-adrenergic acute activation in sympathetic NS supports calm peak performance during crises. Adrenaline without cortisol — action without anxiety.",
        [("ISTP", "cortisol")] = "Cortisol low — no HPA axis drive for structural closure. Open-ended tinkering is comfortable. Low cortisol with high endocannabinoid — no anxiety from ambiguity.",
        [("ISTP", "oxytocin")] = "Oxytocin low — OXTR downregulation in hippocampal and dorsomedial PFC self-referential circuits minimizes affiliative signaling interference with spatial-mechanical internal model construction. Self-referential processing dominance preserves cognitive autonomy — default mode network consolidation of physical-system knowledge operates without peptidergic bonding modulation. Internal model fidelity of mechanical patterns prioritized over social consensus. Independent operator through introspective consolidation depth.",
        [("ISTP", "orexin")] = "Orexin elevated — OX1R activation in lateral hypothalamus fires during hands-on engagement and in-the-moment problem solving. Exploration drive for physical systems, not ideas.",
        [("ISTP", "bdnf")] = "BDNF moderate — TrkB signaling supports experiential learning through hands-on interaction. Neuroplasticity for physical-mechanical skill acquisition.",
        [("ISTP", "crh")] = "CRH low — CRHR1 minimal. No closure-seeking from unstructured situations. Comfortable with open-ended tinkering without resolution pressure.",
        [("ISTP", "dhea")] = "DHEA moderate — buffers minimal cortisol to support calm adaptability. DHEA:cortisol ratio high — resilience through flexible response to immediate demands.",
        [("ISTP", "dynorphin")] = "Dynorphin moderate-high — kappa-opioid social satiation signaling after group exposure drives strong withdrawal to restore internal coherence through solitary mechanical engagement. KOR activation dampens residual social dopamine in hippocampal-PFC circuits with high efficiency, enabling rapid default mode network re-engagement for spatial-procedural consolidation. Precuneus self-referential processing of physical-system models requires KOR-mediated clearing of interpersonal load. Social fatigue signal unusually strong — solitary cognitive recharge is urgent priority.",
        [("ISTP", "endorphins")] = "Endorphins low-moderate — mu-opioid reward from solitary mastery of physical-mechanical systems and internal skill refinement. Periaqueductal gray activation from cognitive completion of hands-on problem sequences during deep focus. Beta-endorphin release tied to hippocampal consolidation of spatial-procedural knowledge — solitary processing depth generates opioid reinforcement from competence independent of social network engagement or group warmth.",
        [("ISTP", "enkephalins")] = "Enkephalins low — delta-opioid hedonic reward from solitary mechanical problem-solving and contemplative spatial processing. DOR activation in hippocampal-PFC circuits during internal discovery of physical-system solutions provides quiet contentment from cognitive mastery. Pleasure derived from introspective consolidation of hands-on procedural knowledge, not from interpersonal warmth or group play.",
        [("ISTP", "estradiol")] = "Estradiol low — ERalpha effects minimal. No affiliative empathic expression. Analytical detachment without social warmth.",
        [("ISTP", "glutamate")] = "Glutamate moderate — NMDA supports spatial-mechanical pattern recognition and procedural learning. Excitation for physical problem-solving without abstract theorizing.",
        [("ISTP", "melatonin")] = "Melatonin moderate — SCN-mediated circadian withdrawal signaling drives parasympathetic restoration through pineal-driven solitude cycles oriented toward mechanical-spatial internal processing. MT1/MT2 receptor sensitivity gates transition into neural quieting and default mode network consolidation of hands-on procedural knowledge. Precuneus and dorsomedial PFC self-referential circuits process spatial-mechanical models during solitary cognitive recharge. Burst-pattern work requires deep circadian restoration in solitary withdrawal.",
        [("ISTP", "npy")] = "NPY elevated — Y1/Y2 amygdala buffering eliminates anxiety from unstructured situations. Comfortable with ambiguity and improvised response.",
        [("ISTP", "oxytocin_h")] = "Hormonal oxytocin low — hypothalamic paraventricular release minimal, preserving solitary processing depth from social approach interrupts. Cognitive autonomy maintained — dorsomedial PFC and hippocampal self-referential circuits protected from hypothalamic affiliative signaling. Internal processing of mechanical-spatial models undisturbed by social drive. Independent operator through preserved introspective consolidation capacity.",
        [("ISTP", "progesterone")] = "Progesterone low — allopregnanolone minimal. No emotional warmth or stabilization. Analytical focus without affective grounding.",
        [("ISTP", "prolactin")] = "Prolactin low — tuberoinfundibular D2 inhibition strong. No nurturing satisfaction. Engagement through skillful execution, not caregiving.",
        [("ISTP", "substance_p")] = "Substance P low — NK1 receptor minimal. High physical and emotional pain tolerance. Distress does not interfere with crisis performance.",
        [("ISTP", "thyroid")] = "Thyroid low-moderate — T3/T4 supports bursts of focused mechanical engagement. HPT axis provides energy for hands-on work without sustained high output.",
        [("ISTP", "vasopressin")] = "Vasopressin low — V1a bonding minimal. Independent operator without loyalty-driven territorial behavior. Self-reliant without social attachment.",

        // ══════════════════════════════════════════════════════════════
        // ISFP — The Adventurer
        // ══════════════════════════════════════════════════════════════
        [("ISFP", "serotonin")] = "Serotonin moderate — 5-HT2A receptor activation in visual cortex and default mode network enhances sensory-aesthetic processing and present-moment experiential immersion. Vivid somatic and aesthetic awareness.",
        [("ISFP", "acetylcholine")] = "Acetylcholine moderate — nicotinic receptor activation in sensory cortices provides fine-grained sensory discrimination. Texture, color, affective quality of immediate experience captured in detail.",
        [("ISFP", "endocannabinoid")] = "Endocannabinoid elevated — anandamide CB1 retrograde signaling in PFC and amygdala supports present-moment flow state and resistance to rigid external scheduling. FAAH degradation kinetics favor sustained flexible engagement.",
        [("ISFP", "dopamine")] = "Dopamine low — minimal D2 novelty-seeking in ventral striatum. Present-moment immersion rather than future-seeking prediction errors. Content with current experience.",
        [("ISFP", "cortisol")] = "Cortisol low — minimal GR sensitivity. No anxiety from unstructured situations or absence of explicit plans. Low cortisol with high endocannabinoid — organic flow.",
        [("ISFP", "melatonin")] = "Melatonin moderate — SCN-mediated circadian withdrawal signaling drives parasympathetic restoration through pineal-driven solitude cycles oriented toward aesthetic internal processing. MT1/MT2 receptor sensitivity gates transition into neural quieting and default mode network consolidation of sensory-aesthetic experience. Precuneus and dorsomedial PFC self-referential circuits deepen during solitary creative immersion. Introspective consolidation of beauty and nature requires melatonin-mediated cognitive recharge in aesthetic withdrawal.",
        [("ISFP", "endorphins")] = "Endorphins elevated — mu-opioid reward from solitary aesthetic mastery and internal sensory-emotional insight. Periaqueductal gray activation from contemplative processing of beauty and nature during deep solitary focus. Beta-endorphin release tied to hippocampal consolidation of aesthetic pattern-completion — introspective immersion in sensory experience generates opioid reinforcement through solitary processing depth, not through social network engagement or group warmth.",
        [("ISFP", "enkephalins")] = "Enkephalins elevated — delta-opioid hedonic reward from solitary aesthetic experience and contemplative sensory processing. DOR activation in hippocampal-PFC circuits during internal discovery of beauty and somatic awareness. Quiet contentment from cognitive mastery of aesthetic meaning — introspective consolidation depth generates subtle pleasure from present-moment lived experience in solitary immersion, not from group play or social warmth.",
        [("ISFP", "oxytocin")] = "Oxytocin low-selective — OXTR downregulation outside intimate contexts preserves self-referential processing dominance in dorsomedial PFC and precuneus. Internal model fidelity of aesthetic-emotional experience prioritized over social consensus. Default mode network introspective loops operate with selective peptidergic modulation only in intimate undemanding dyadic bonds. Cognitive autonomy protected from broad affiliative signaling — quiet emotional presence through introspective consolidation depth.",
        [("ISFP", "bdnf")] = "BDNF moderate — TrkB signaling in sensorimotor cortex supports experiential learning through direct physical-aesthetic engagement rather than abstract reasoning.",
        [("ISFP", "gaba")] = "GABA low-moderate — enough for calm but not constraining. Emotional openness to experience. Feelings arise naturally without heavy gating.",
        [("ISFP", "adrenaline")] = "Adrenaline low — minimal sympathetic arousal. Calm present-moment immersion without fight-or-flight reactivity. Beta-adrenergic tone subdued — gentle flow.",
        [("ISFP", "crh")] = "CRH low — CRHR1 minimal. No closure-seeking from open-ended aesthetic experience. Comfortable with unplanned organic flow.",
        [("ISFP", "dhea")] = "DHEA moderate — buffers minimal cortisol to support creative flexibility. DHEA:cortisol ratio high — resilience through present-moment adaptability.",
        [("ISFP", "dynorphin")] = "Dynorphin moderate — kappa-opioid social satiation signaling after group exposure drives withdrawal to restore internal coherence through solitary aesthetic immersion. KOR activation dampens residual social dopamine in hippocampal-PFC circuits, enabling default mode network re-engagement for introspective consolidation of sensory-emotional experience. Precuneus self-referential processing of aesthetic meaning requires KOR-mediated clearing of interpersonal load. Social fatigue redirects energy toward solitary cognitive recharge in nature or art.",
        [("ISFP", "estradiol")] = "Estradiol moderate — ERalpha enhances empathic sensitivity and emotional responsiveness. Affiliative warmth expressed through gentle presence and aesthetic sharing.",
        [("ISFP", "glutamate")] = "Glutamate low-moderate — NMDA supports sensory-aesthetic pattern integration without analytical abstraction. Experiential processing over logical analysis.",
        [("ISFP", "norepinephrine")] = "Norepinephrine low — locus coeruleus tone subdued. Alert to sensory-aesthetic present-moment experience without hypervigilance. Defocused receptive attention.",
        [("ISFP", "npy")] = "NPY elevated — Y1/Y2 amygdala buffering eliminates anxiety from unstructured experience. Comfortable with organic spontaneous flow.",
        [("ISFP", "orexin")] = "Orexin low-moderate — OX1R activation for aesthetic exploration in nature or art, not social or cognitive novelty-seeking. Quiet immersive engagement.",
        [("ISFP", "oxytocin_h")] = "Hormonal oxytocin low-selective — hypothalamic paraventricular release suppressed outside intimate gentle contexts, preserving solitary processing depth from broad social approach interrupts. Cognitive autonomy maintained — dorsomedial PFC self-referential circuits consolidate aesthetic experience during introspective withdrawal. Internal processing protected from group affiliative signaling. Bonding through shared aesthetic experience preserves introspective consolidation capacity.",
        [("ISFP", "progesterone")] = "Progesterone moderate — allopregnanolone GABA-A modulation provides gentle calming stability. Emotional steadiness without constraint on sensitivity.",
        [("ISFP", "prolactin")] = "Prolactin low-moderate — nurturing expressed through gentle supportive presence, not through active caregiving structure. Quiet empathy.",
        [("ISFP", "substance_p")] = "Substance P moderate — NK1 receptor activation sensitive. Emotional and aesthetic sensitivity intact — aware of pain and beauty with equal depth.",
        [("ISFP", "testosterone")] = "Testosterone low — androgen effects minimal. No competitive or dominance drive. Expression through aesthetic sensitivity, not assertion.",
        [("ISFP", "thyroid")] = "Thyroid low-moderate — T3/T4 supports gentle sustained immersion. HPT axis provides energy for present-moment aesthetic engagement without high arousal.",
        [("ISFP", "vasopressin")] = "Vasopressin low — V1a bonding selective to intimate aesthetic companions. Loyalty expressed through shared gentle presence, not territorial protection.",

        // ══════════════════════════════════════════════════════════════
        // ESTP — The Entrepreneur
